package org.localpilot.android;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;
/** Verified symbolic transitions, never PPO rollouts. Import cannot overwrite existing samples. */
public final class ExperienceStore {
 public static final class Full extends IOException {public Full(){super("experience capacity reached; existing examples preserved");}}
 public static final int MAX=262144,MAX_ROWS=256;
 private static final String HEADER="LOCALPILOT-EXPERIENCE-v1\n";
 private final File file,lockFile;
 public ExperienceStore(File file)throws IOException{this.file=file;lockFile=new File(file.getPath()+".lock");File parent=file.getParentFile();if(parent!=null&&!parent.isDirectory()&&!parent.mkdirs())throw new IOException("directory");if(file.exists())validate(read(file));}
 public static byte[] bounded(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>MAX)throw new IOException("experience size limit");out.write(b,0,n);}return out.toByteArray();}
 private static byte[] read(File f)throws IOException{if(!f.exists())return HEADER.getBytes(StandardCharsets.UTF_8);if(f.length()>MAX)throw new IOException("experience size");try(InputStream in=new FileInputStream(f)){return bounded(in);}}
 private static String hash(String s)throws IOException{try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:digest)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}catch(NoSuchAlgorithmException e){throw new IOException(e);}}
 private static String board(int[] b){StringBuilder s=new StringBuilder();for(int v:b){if(s.length()>0)s.append(',');s.append(v);}return s.toString();}
 private static int[] parse(String s){String[] p=s.split(",",-1);if(p.length>25)throw new IllegalArgumentException();int[] b=new int[p.length];for(int i=0;i<p.length;i++)b[i]=Integer.parseInt(p[i]);return b;}
 private static int reward(String profile,int[] before,int action,int[] after){if(profile.equals("2048")){if(action<0||action>3)throw new IllegalArgumentException();return Verified2048.mergeReward(new Board2048(before),action,new Board2048(after));}int kind=profile.equals("ttt")?0:profile.equals("lights")?1:-1;if(kind==0){MiniPolicy.validate(0,before);int x=0,o=0;for(int v:before){if(v==1)x++;if(v==2)o++;}if(x!=o||MiniPolicy.winner(before)!=0)throw new IllegalArgumentException("not X turn");}if(kind<0||!MiniPolicy.verifies(kind,before,action,after))throw new IllegalArgumentException("unverified transition");return 0;}
 /** Header + seq|profile|action|reward|before|after|ppo=false|prev|hash. Imported claims are not authenticated. */
 public static int validate(byte[] data)throws IOException{if(data.length>MAX)throw new IOException("size");String text=new String(data,StandardCharsets.UTF_8);if(!Arrays.equals(data,text.getBytes(StandardCharsets.UTF_8))||!text.startsWith(HEADER)||!text.endsWith("\n"))throw new IOException("format/truncated");String rest=text.substring(HEADER.length());if(rest.isEmpty())return 0;String previous="0";int count=0;for(String line:rest.substring(0,rest.length()-1).split("\n",-1)){if(line.isEmpty())throw new IOException("blank record");String[] p=line.split("\\|",-1);try{if(p.length!=9||Integer.parseInt(p[0])!=count+1||!p[6].equals("ppo=false")||!p[7].equals(previous)||Integer.parseInt(p[3])!=reward(p[1],parse(p[4]),Integer.parseInt(p[2]),parse(p[5])))throw new IllegalArgumentException();String body=line.substring(0,line.lastIndexOf('|'));if(!hash(body).equals(p[8]))throw new IllegalArgumentException();previous=p[8];if(++count>MAX_ROWS)throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw new IOException("invalid sample",e);}}return count;}
 public synchronized byte[] snapshot()throws IOException{byte[] b=read(file);validate(b);return b;}
 private void commit(byte[] data)throws IOException{File temp=File.createTempFile("experience-", ".pending",file.getAbsoluteFile().getParentFile());try{try(FileOutputStream out=new FileOutputStream(temp)){out.write(data);out.getFD().sync();}validate(read(temp));Files.move(temp.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp.toPath());}}
 public synchronized void append(String profile,int[] before,int action,int[] after)throws IOException{int r;try{r=reward(profile,before,action,after);}catch(IllegalArgumentException e){throw new IOException("unverified sample",e);}try(RandomAccessFile handle=new RandomAccessFile(lockFile,"rw");java.nio.channels.FileLock ignored=handle.getChannel().lock()){byte[] old=snapshot();int count=validate(old);if(count>=MAX_ROWS)throw new Full();String text=new String(old,StandardCharsets.UTF_8),previous="0";if(count>0){String last=text.substring(0,text.length()-1);previous=last.substring(last.lastIndexOf('|')+1);}String body=(count+1)+"|"+profile+"|"+action+"|"+r+"|"+board(before)+"|"+board(after)+"|ppo=false|"+previous;byte[] next=(text+body+"|"+hash(body)+"\n").getBytes(StandardCharsets.UTF_8);if(next.length>MAX)throw new Full();validate(next);commit(next);}catch(java.nio.channels.OverlappingFileLockException e){throw new IOException("store busy",e);}}
 public synchronized int restoreEmpty(byte[] imported)throws IOException{int count=validate(imported);try(RandomAccessFile handle=new RandomAccessFile(lockFile,"rw");java.nio.channels.FileLock ignored=handle.getChannel().lock()){if(validate(read(file))!=0)throw new IOException("restore refused: existing samples preserved");commit(imported);return count;}catch(java.nio.channels.OverlappingFileLockException e){throw new IOException("store busy",e);}}
}
